CREATE TABLE IF NOT EXISTS "crc01_nutrimento" ("id_nutrimento" INTEGER NOT NULL,"tx_nombre" VARCHAR(150) NOT NULL,"tx_descripcion" TEXT NOT NULL,"st_activo" BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY("id_nutrimento"));
CREATE TABLE IF NOT EXISTS "crc02_tipo_etiqueta" ("id_tipo_etiqueta" INTEGER NOT NULL,"tx_nombre" VARCHAR(100) NOT NULL,"tx_descripcion" TEXT NOT NULL,"st_activo" BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY("id_tipo_etiqueta"));
CREATE TABLE IF NOT EXISTS "crc03_tipo_cantidad_ingrediente" ("id_tipo_cantidad_ingrediente" INTEGER NOT NULL,"tx_nombre" VARCHAR(100) NOT NULL,"tx_descripcion" TEXT NOT NULL,"st_activo" BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY("id_tipo_cantidad_ingrediente"));
CREATE TABLE IF NOT EXISTS "trc01_receta" ("id_receta" SERIAL NOT NULL,"tx_nombre" VARCHAR(100) NOT NULL,"tx_descripcion" TEXT,"tm_tiempo_preparacion" TIME,"fh_creacion" TIMESTAMP NOT NULL,"fh_actualizacion" TIMESTAMP NOT NULL,"nu_veces_realizada" INTEGER NOT NULL,"fh_ultima_realizacion" TIMESTAMP,PRIMARY KEY("id_receta"));
CREATE TABLE IF NOT EXISTS "trc02_ingrediente" ("id_ingrediente" SERIAL NOT NULL,"tx_nombre" VARCHAR(100) NOT NULL,PRIMARY KEY("id_ingrediente"));
CREATE TABLE IF NOT EXISTS "trc03_etiqueta" ("id_etiqueta" SERIAL NOT NULL,"fk_id_tipo" INTEGER NOT NULL,"tx_nombre" VARCHAR(100) NOT NULL,"tx_color" VARCHAR(8) NOT NULL,PRIMARY KEY("id_etiqueta"));
CREATE TABLE IF NOT EXISTS "trc04_instruccion" ("id_instruccion" SERIAL NOT NULL,"tx_instruccion" TEXT NOT NULL,"nu_orden" INTEGER NOT NULL,PRIMARY KEY("id_instruccion"));
CREATE TABLE IF NOT EXISTS "trc05_receta_ingrediente" ("fk_id_receta" INTEGER NOT NULL,"fk_id_ingrediente" INTEGER NOT NULL,"fk_id_tipo_cantidad" INTEGER NOT NULL,"db_cantidad" DOUBLE PRECISION,"tx_cantidad" VARCHAR(100),PRIMARY KEY("fk_id_receta", "fk_id_ingrediente"));
CREATE TABLE IF NOT EXISTS "trc06_receta_etiqueta" ("fk_id_receta" INTEGER NOT NULL,"fk_id_etiqueta" INTEGER NOT NULL,PRIMARY KEY("fk_id_receta", "fk_id_etiqueta"));
CREATE TABLE IF NOT EXISTS "trc07_ingrediente_etiqueta" ("fk_id_ingrediente" INTEGER NOT NULL,"fk_id_etiqueta" INTEGER NOT NULL,PRIMARY KEY("fk_id_ingrediente", "fk_id_etiqueta"));
CREATE TABLE IF NOT EXISTS "trc08_nutrimento_ingrediente" ("fk_id_nutrimento" INTEGER NOT NULL,"fk_id_ingrediente" INTEGER NOT NULL,"db_porcentaje" DOUBLE PRECISION,PRIMARY KEY("fk_id_nutrimento", "fk_id_ingrediente"));
CREATE TABLE IF NOT EXISTS "trc09_subproducto" ("id_subproducto" SERIAL NOT NULL UNIQUE,"fk_id_receta" INTEGER NOT NULL,"tx_nombre" VARCHAR(100) NOT NULL,"tx_descripcion" TEXT,"tm_tiempo_preparacion" TIME NOT NULL,"nu_orden" INTEGER NOT NULL,PRIMARY KEY("id_subproducto"));
CREATE TABLE IF NOT EXISTS "trc10_instruccion_receta" ("fk_id_instruccion" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,"fk_id_receta" INTEGER NOT NULL,PRIMARY KEY("fk_id_instruccion", "fk_id_receta"));
CREATE TABLE IF NOT EXISTS "trc11_instruccion_subproducto" ("fk_id_instruccion" INTEGER NOT NULL UNIQUE GENERATED BY DEFAULT AS IDENTITY,"fk_id_subproducto" INTEGER NOT NULL,PRIMARY KEY("fk_id_instruccion", "fk_id_subproducto"));

